const InteractiveGrid = () => {
  const gridRef = useRef<HTMLDivElement>(null);
  const dotSize = 10;
  const gap = 30;

  useEffect(() => {
    const grid = gridRef.current;
    if (!grid) return;

    const numCols = Math.floor(window.innerWidth / (dotSize + gap));
    const numRows = Math.floor(window.innerHeight / (dotSize + gap));
    const dots: HTMLDivElement[] = [];

    grid.innerHTML = ''; // Clear previous dots

    for (let i = 0; i < numCols * numRows; i++) {
      const dot = document.createElement('div');
      dot.classList.add(styles.dot);
      grid.appendChild(dot);
      dots.push(dot);
    }

    const handleMouseMove = (e: MouseEvent) => {
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      dots.forEach(dot => {
        const rect = dot.getBoundingClientRect();
        const dotX = rect.left + rect.width / 2;
        const dotY = rect.top + rect.height / 2;

        const distance = Math.sqrt(Math.pow(dotX - mouseX, 2) + Math.pow(dotY - mouseY, 2));
        const maxDist = 200;
        
        if (distance < maxDist) {
          const scale = 1 + (1 - distance / maxDist) * 2;
          const opacity = 0.5 + (1 - distance / maxDist) * 0.5;
          dot.style.transform = `scale(${scale})`;
          dot.style.opacity = `${opacity}`;
        } else {
          dot.style.transform = 'scale(1)';
          dot.style.opacity = '0.5';
        }
      });
    };

    window.addEventListener('mousemove', handleMouseMove);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  return <div ref={gridRef} className={styles.gridContainer}></div>;
};


